{
  "items": [
    {
      "concept_name": {
        "text": "tool-augmented chatbot",
        "refs": ["Q0000"],
        "claims": [
          {
            "text": "LLM can be given tools like a screw driver or a phone, making a tool-augmented chatbot.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0000"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "A chatbot that uses external tools (e.g., scheduling, HR systems) to perform tasks beyond simple Q&A.",
        "refs": ["Q0005", "Q0006", "Q0007", "Q0008"],
        "claims": [
          {
            "text": "The chatbot can create onboarding checklists, schedule meetings, and send access requests by using tools.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0005", "Q0006"],
            "related_refs": []
          },
          {
            "text": "It has access to all these tools when building an agentic AI system.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0007", "Q0008"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "agentic AI system",
        "refs": ["Q0015"],
        "claims": [
          {
            "text": "A chatbot that can perform multi-step planning and act autonomously is an agentic AI system.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0015"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "An AI system that combines LLM reasoning with tool access to achieve goals.",
        "refs": ["Q0014", "Q0018", "Q0019"],
        "claims": [
          {
            "text": "It extracts details, accesses tools, and performs actions toward a goal.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0014"],
            "related_refs": []
          },
          {
            "text": "Goal-oriented planning replaces simple reactive Q&A.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0018"],
            "related_refs": []
          },
          {
            "text": "The system performs autonomous decision‑making and executes actions.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0019"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "goal‑oriented planning",
        "refs": ["Q0017"],
        "claims": [
          {
            "text": "The first characteristic of an agentic AI system is goal‑oriented planning.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0017"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Providing a goal (e.g., onboard a new intern) and letting the AI devise a multi‑step plan using tools.",
        "refs": ["Q0018", "Q0019"],
        "claims": [
          {
            "text": "You give the AI a goal and access to tools; it creates a plan and executes steps.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0018"],
            "related_refs": []
          },
          {
            "text": "The AI performs multi‑step reasoning, goal‑oriented planning, and autonomous decision‑making.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0019"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "knowledge and memory",
        "refs": ["Q0009"],
        "claims": [
          {
            "text": "Agentic AI systems rely on knowledge, memory, etc., in addition to tools.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0009"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "These components support reasoning and planning across steps.",
        "refs": ["Q0010"],
        "claims": [
          {
            "text": "The reasoning model uses knowledge and memory to create a plan and perform steps.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0010"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    }
  ],
